  r,h=2+n,6+n
  add('advanced','cylinder',n,'円柱の体積',f'底面の半径{r}cm、高さ{h}cmの円柱。体積は？ 円周率は3.14。',F(314*r*r*h,100),
   f'底面積は{r}×{r}×3.14。それを高さ{h}cmぶん積み、{number(F(314*r*r*h,100))}cm³です。','円の底面積に高さを掛けるから',dict(r=r,h=h),visual='cylinder',unit='cm³',action='底面を積み上げて見る')
  # EXPERT: multi-step entrance-exam constructions, not renamed elementary items.
