def cm_json(value):return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False)
def cm_hash(value):return hashlib.sha256(cm_json(value).encode()).hexdigest()
def cm_utc(value):
    if not isinstance(value,str) or len(value)>40:raise ValueError('invalid UTC time')
    d=datetime.fromisoformat(value.replace('Z','+00:00'))
    if d.tzinfo is None or d.utcoffset().total_seconds()!=0:raise ValueError('UTC time required')
    return d.astimezone(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def cm_now():return datetime.now(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def cm_choice_id(text):return 'choice.'+cm_hash(str(text))[:24]

def cm_build_catalog(bank):
    questions=[];meta={};skills={}
    for q in bank:
        family=q['family'];skill='geometry.'+family
        choices={cm_choice_id(c):c for c in q['choices']}
        semantic={'family':family,'prompt':q['prompt'],'params':q['params'],'choices':choices,'correct':cm_choice_id(q['choices'][q['answer']])}
        content_hash=cm_hash(semantic);qid='geometry.'+family+'.'+content_hash[:24]
        snapshot={'source_question_id':q['id'],'prompt':q['prompt'],'choices':choices,'params':q['params'],'visual':q['visual'],'hints':q['hints'],'explanation':q['explanation'],'learning':q['learning']}
        questions.append({'question_id':qid,'question_family_id':'geometry.'+family,'skill_ids':[skill],'menu_ids':['geometry.level.'+q['level']],'difficulty_id':q['level'],'difficulty_axes':{'course_level':q['level'],'parameters':q['params']},'content_hash':content_hash,'assessment_method':'automatic','response_format':'choice','correct_answer_spec':{'choice_id':semantic['correct'],'evaluator_version':'geometry.choice.v12'},'choice_ids':sorted(choices),'choice_count':len(choices),'passage_id':None,'related_material_id':'geometry.figure.'+cm_hash({'visual':q['visual'],'params':q['params']})[:24],'is_generated':True,'generator_id':'geometry.course_bank','generator_version':'12','instance_parameters':q['params'],'is_active':True,'snapshot':snapshot,'solution_version':'geometry.hints.'+cm_hash(q['hints'])[:16]})
        meta[q['id']]={'question_id':qid,'question_family_id':'geometry.'+family,'skill_ids':[skill],'menu_id':'geometry.level.'+q['level'],'choice_order':[cm_choice_id(c) for c in q['choices']],'related_material_id':questions[-1]['related_material_id']}
        skills[skill]={'skill_id':skill,'label':q['skill'],'parent_skill_id':None,'category_id':q['learning']['category'],'definition':q['learning']['discovery'],'observation_rule':'選択回答の正誤と、回答前に表示した支援を別に記録する。理由回答は未取得。探索操作だけで理解済みと判定しない。','prerequisite_skill_ids':None,'progression_group_id':'geometry.course','difficulty_axes':{'course_level':q['level']},'is_active':True}
    version='geometry.course.'+cm_hash({'questions':sorted(questions,key=lambda q:q['question_id']),'menu_schema':'13-provisional180s-review1to4','launch_url':setting('GEOMETRY_APP_URL') or None})[:20]
    entries=[]
    def add(kind,eid,payload):entries.append(dict(schema_version=1,source_app='geometry',entry_type=kind,entry_id=eid,content_version=version,payload=payload))
    for order,(level,definition) in enumerate(LEVELS.items(),1):
        ids=sorted({m['skill_ids'][0] for qid,m in meta.items() if BY_ID[qid]['level']==level})
        add('menu','geometry.level.'+level,{'menu_id':'geometry.level.'+level,'label':definition['name'],'category_id':'geometry','category_label':'図形','difficulty_id':level,'difficulty_label':definition['name'],'difficulty_order':order,'progression_group_id':'geometry.course','skill_ids':ids,'prerequisite_skill_ids':None,'mode_options':['challenge','review'],'question_count_default':4,'question_count_options':[1,2,3,4],'estimated_duration_ms':180000,'duration_basis':'provisional','duration_sample_count':0,'duration_estimate_note':'4問×45秒の運用上の仮設定。実測値・科学的推奨時間ではない。','next_menu_ids':(['geometry.level.'+list(LEVELS)[order]] if order<len(LEVELS) else []),'age_min':None,'age_max':None,'age_basis':None,'launch_url':setting('GEOMETRY_APP_URL') or None,'supports_direct_launch':False,'selection_instructions':'チャレンジまたは苦手克服を選び、級を選択する。','is_active':True,'available_skill_ids':ids})
    for skill,p in sorted(skills.items()):add('skill',skill,p)
    for q in questions:add('question',q['question_id'],q)
    for m in meta.values():m['content_version']=version
    return version,entries,meta

