        if kind=='time_interval_closed':
            if p['phase'] not in ('prompt','thinking','answering','feedback','explanation','exploration','reading_aloud','other'):raise ValueError('invalid time phase')
            if p['timing_quality'] not in CM_TIMING:raise ValueError('invalid timing quality')
            start,end=cm_utc(p['start_at']),cm_utc(p['end_at']);cm_int(p['elapsed_ms']);cm_int(p['active_ms'],nullable=True)
            delta=round((datetime.fromisoformat(end.replace('Z','+00:00'))-datetime.fromisoformat(start.replace('Z','+00:00'))).total_seconds()*1000)
            if delta<0 or abs(delta-p['elapsed_ms'])>3:raise ValueError('interval bounds mismatch')
            if p['active_ms'] is not None and p['active_ms']>p['elapsed_ms']:raise ValueError('active time exceeds interval')
            cm_require_keys(p['excluded_ms'],['hidden','explicit_pause','blocking_wait'])
