    # For local unlinked exports use start.local_learner_id for all events in its attempt.
    unlinked_owner={e['attempt_id']:e['payload'].get('local_learner_id','unlinked') for e in rows if e['event_type']=='session_started' and not e.get('profile_id')}
    if unlinked_owner:
        repaired=[]
        for e in rows:
            e=dict(e)
            if not e.get('profile_id') and e['attempt_id'] in unlinked_owner:e['profile_id']='unlinked:'+unlinked_owner[e['attempt_id']]
            repaired.append(e)
        if any(not e.get('profile_id') and e['attempt_id'] in unlinked_owner for e in rows):
            result=summarize_learning_events(repaired,catalog);result['unlinked_attempt_count']=len(unlinked_owner);return result
    groups={};progress={};time_by_owner={};daily={};attempt_durations=[];unknown_times=[]
    menus={(e['content_version'],e['entry_id']):e['payload'] for e in catalog if e['entry_type']=='menu'}
    questions={(e['content_version'],e['entry_id']):e['payload'] for e in catalog if e['entry_type']=='question'}
    for key,item in items.items():
        who=owner(item);start=starts.get((who,item['attempt_id']));p=item['payload']
        if not start:continue
        sp=start['payload'];pk=(who,item['content_version'],sp['menu_id'])
        available=menus.get((item['content_version'],sp['menu_id']),{}).get('available_skill_ids')
        pr=progress.setdefault(pk,{'profile_id':who[0],'source_app':who[1],'content_version':item['content_version'],'menu_id':sp['menu_id'],'available_skill_ids':available,'contacted':set(),'answered':set()});pr['contacted'].update(p['skill_ids'])
        # Response ordering uses the declared occurrence-local response index.
        rr=sorted(responses.get(key,[]),key=lambda e:(e['payload']['response_index'],e['segment_id'],e['sequence']))
        dedup={}
        for response in rr:
            rid=response['payload']['response_id']
            if rid not in dedup:dedup[rid]=response
        rr=list(dedup.values())
        for response in rr:
            rp=response['payload'];condition={'settings':sp['settings_snapshot'],'input_method':rp['input_method'],'mode':sp['mode']}
            for skill in p['skill_ids']:
                groupkey=(who,skill,item['content_version'],sp['difficulty_id'],rp['assessment_method'],cm_json(condition))
                g=groups.setdefault(groupkey,{'profile_id':who[0],'source_app':who[1],'skill_id':skill,'content_version':item['content_version'],'progression_group_id':sp['progression_group_id'],'difficulty_id':sp['difficulty_id'],'assessment_method':rp['assessment_method'],'conditions':condition,'initial_answer_correct':0,'initial_answer_denominator':0,'independent_first_correct':0,'independent_first_denominator':0,'excluded':{},'supported_correct':{'hint':0,'worked_example':0,'retry':0},'status_counts':{'answered':0,'dont_know':0,'skipped':0,'timed_out':0},'answer_latency_ms':[],'timing_quality_counts':{},'evidence':[],'review_candidates':[],'retention_evidence':[],'transfer_evidence':[],'trend_by_day':{},'_successes':[]})
                g['status_counts'][rp['response_status']]+=1
                if rp['response_status']=='answered':pr['answered'].add(skill)
                if rp['answer_latency_ms'] is not None:g['answer_latency_ms'].append(rp['answer_latency_ms'])
                tq=rp['timing_quality'];g['timing_quality_counts'][tq]=g['timing_quality_counts'].get(tq,0)+1
                root=p['parent_occurrence_id'] is None and p['retry_index']==0;first=rp['response_index']==1;objective=rp['assessment_method']=='automatic' and rp['response_status']=='answered' and type(rp['is_correct']) is bool
                if root and first and objective:g['initial_answer_denominator']+=1;g['initial_answer_correct']+=int(rp['is_correct'])
                support=rp['support_before_response'];reason=None
                if not root or not first:reason='retry_or_resubmission'
                elif not objective:reason='not_objectively_scored_answer'
                elif p.get('answer_exposed_before') is not False:reason='prior_answer_exposure_or_unknown'
                elif any(support.get(k) is None for k in ('hint_count','max_hint_step','explanation_seen','answer_seen','worked_example_seen','parent_help')):reason='support_observation_incomplete'
                elif support['hint_count'] or support['explanation_seen'] or support['answer_seen'] or support['worked_example_seen'] or support['parent_help']:reason='support_before_answer'
                if reason:g['excluded'][reason]=g['excluded'].get(reason,0)+1
                else:g['independent_first_denominator']+=1;g['independent_first_correct']+=int(rp['is_correct'])
                day=at(response).astimezone(ZoneInfo('Asia/Tokyo')).date().isoformat()
                if root and first and objective:
                    t=g['trend_by_day'].setdefault(day,{'correct':0,'denominator':0});t['correct']+=int(rp['is_correct']);t['denominator']+=1
