CHOKOMANA_SETUP_SQL = "-- Project kotoba_app (keewulninyoeylgflshb), existing common schema checked 2026-11-09 UTC.\n-- Add only the missing geometry writer. Existing shared tables/RLS are reused. Do not recreate tables or alter existing RLS/GRANTs.\nbegin;\ncreate or replace function public.chokomana_append_geometry_events_v1(p_device_hash text,p_events jsonb)\nreturns jsonb language plpgsql security invoker set search_path='' as $$\ndeclare v_profile text;v jsonb;r public.chokomana_learning_events;stored jsonb;ids jsonb:='[]';\nbegin\n if p_device_hash !~ '^[a-f0-9]{64}$' then raise exception 'invalid device proof';end if;\n select profile_id::text into v_profile from public.chokomana_device_links where device_hash=p_device_hash and source_app='geometry';\n if v_profile is null then raise exception 'unverified profile' using errcode='42501';end if;\n if jsonb_typeof(p_events)<>'array' or jsonb_array_length(p_events)>100 or pg_column_size(p_events)>1048576 then raise exception 'invalid_batch';end if;\n for v in select value from jsonb_array_elements(p_events) loop\n  if v->>'profile_id' is distinct from v_profile or v->>'source_app' is distinct from 'geometry' then raise exception 'event owner mismatch' using errcode='42501';end if;\n  if (v->>'schema_version')::int<>1 or coalesce(v->>'event_hash','') !~ '^[a-f0-9]{64}$' then raise exception 'invalid schema or hash';end if;\n  r:=jsonb_populate_record(null::public.chokomana_learning_events,v);r.received_at:=now();\n  insert into public.chokomana_learning_events select r.* on conflict(event_id) do nothing;\n  select to_jsonb(e)-'received_at' into stored from public.chokomana_learning_events e where e.event_id=r.event_id;\n  if stored is distinct from to_jsonb(r)-'received_at' then raise exception 'event_id_content_conflict' using errcode='23505';end if;\n  ids:=ids||jsonb_build_array(r.event_id);\n end loop;\n return jsonb_build_object('acked',ids);\nend $$;\nrevoke all on function public.chokomana_append_geometry_events_v1(text,jsonb) from public,anon,authenticated;\ngrant execute on function public.chokomana_append_geometry_events_v1(text,jsonb) to service_role;\ncommit;\n"
